import heapq, math
# Grid graph 30x30, unit edges. Count nodes expanded by Dijkstra vs A*.
N = 30
def search(start, goal, use_h):
    h = lambda p: abs(p[0]-goal[0]) + abs(p[1]-goal[1]) if use_h else 0  # Manhattan: admissible
    dist = {start: 0}
    pq = [(h(start), start)]
    done = set()
    while pq:
        _, u = heapq.heappop(pq)
        if u in done:
            continue
        done.add(u)                      # u is expanded
        if u == goal:
            return dist[u], len(done)
        for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
            v = (u[0]+dx, u[1]+dy)
            if 0 <= v[0] < N and 0 <= v[1] < N and dist[u] + 1 < dist.get(v, 1e9):
                dist[v] = dist[u] + 1
                heapq.heappush(pq, (dist[v] + h(v), v))
    return None

s, g = (15, 15), (25, 20)
print("grid", N, "x", N, "from", s, "to", g)
for name, flag in (("Dijkstra", False), ("A*", True)):
    d, n = search(s, g, flag)
    print(name, "distance", d, "nodes expanded", n)

