// Atomic all-or-nothing seat hold with TTL, seats sorted to keep a global order.
const holds = new Map(); // seat -> {user, expires}
let now = 0;             // fake clock in seconds

function holdSeats(user, seats, ttl) {
  const ordered = [...seats].sort(); // same lock order for everyone: no deadlock
  // check phase (JS is single-threaded, so this block is atomic like a Redis script)
  for (const s of ordered) {
    const h = holds.get(s);
    if (h && h.expires > now && h.user !== user) return false; // taken
  }
  for (const s of ordered) holds.set(s, { user, expires: now + ttl });
  return true;
}

console.log("A holds A1,A2:", holdSeats("alice", ["A2", "A1"], 600));
console.log("B holds A2,A3:", holdSeats("bob", ["A3", "A2"], 600));
console.log("A3 still free for bob alone:", holdSeats("bob", ["A3"], 600));
now = 601; // ten minutes pass, alice never paid
console.log("after TTL, B holds A1:", holdSeats("bob", ["A1"], 600));
console.log("holds:", [...holds].map(([s, h]) => s + "=" + h.user).join(" "));

