# Trie where every node caches its top-K completions (built offline from counts).
K = 3
queries = {"apple": 90, "app store": 70, "application": 50, "apply": 30, "banana": 80, "band": 40}

class Node:
    def __init__(self):
        self.kids = {}
        self.top = []   # (count, query) best K under this prefix

root = Node()
for q, c in queries.items():
    node = root
    for ch in q:
        node = node.kids.setdefault(ch, Node())
        node.top.append((c, q))
        node.top = sorted(node.top, reverse=True)[:K]   # keep only K

def suggest(prefix):
    node = root
    for ch in prefix:               # O(len(prefix)) walk, no subtree scan
        node = node.kids.get(ch)
        if node is None:
            return []
    return [q for _, q in node.top]

print("queries:", queries)
for p in ("a", "app", "ban", "x"):
    print(repr(p), "->", suggest(p))
